"""Encoder/decoder round-trip for the complex base beta = i - 1."""
from __future__ import annotations
from typing import List, Tuple

GaussInt = Tuple[int, int]
BETA: GaussInt = (-1, 1)  # beta = i - 1

def forced_digit(z: GaussInt) -> int:
    return (z[0] + z[1]) % 2

def next_gi(z: GaussInt) -> GaussInt:
    d = forced_digit(z)
    a, b = z[0] - d, z[1]
    return ((b - a) // 2, -(a + b) // 2)

def encode(z: GaussInt) -> List[int]:
    bits: List[int] = []
    while z != (0, 0):
        bits.append(forced_digit(z))
        z = next_gi(z)
    return bits

def decode(bits: List[int]) -> GaussInt:
    re, im = 0, 0
    pr, pi = 1, 0
    for d in bits:
        if d:
            re, im = re + pr, im + pi
        pr, pi = (-pr - pi), (pr - pi)  # multiply power by beta
    return (re, im)

if __name__ == "__main__":
    for z in [(0, 0), (1, 0), (0, 1), (0, -1), (-1, 0), (2, 3), (-5, 7)]:
        bits = encode(z)
        s = "".join(str(d) for d in reversed(bits)) or "(empty)"
        print(f"{z!s:>9} -> {s:<12} decode={decode(bits)}")

"""Locate the finite set of points where the Gaussian norm fails to decrease."""
from __future__ import annotations
from typing import List, Tuple

GaussInt = Tuple[int, int]

def forced_digit(z: GaussInt) -> int:
    return (z[0] + z[1]) % 2

def next_gi(z: GaussInt) -> GaussInt:
    d = forced_digit(z)
    a, b = z[0] - d, z[1]
    return ((b - a) // 2, -(a + b) // 2)

def gnorm(z: GaussInt) -> int:
    return z[0] * z[0] + z[1] * z[1]

def exceptional_points(radius: int = 60) -> List[GaussInt]:
    bad: List[GaussInt] = []
    for a in range(-radius, radius + 1):
        for b in range(-radius, radius + 1):
            z = (a, b)
            if z != (0, 0) and gnorm(next_gi(z)) >= gnorm(z):
                bad.append(z)
    return bad

if __name__ == "__main__":
    pts = exceptional_points()
    print(f"{len(pts)} nonzero non-decreasing points: {sorted(pts)}")
    for z in sorted(pts):
        w = next_gi(z)
        print(f"  {z} -> {w}   N: {gnorm(z)} -> {gnorm(w)}")

"""Empirically confirm the parity-recovery identity: LSB(z) = (Re+Im) mod 2."""
from __future__ import annotations
from typing import Tuple

GaussInt = Tuple[int, int]

def forced_digit(z: GaussInt) -> int:
    return (z[0] + z[1]) % 2

def next_gi(z: GaussInt) -> GaussInt:
    d = forced_digit(z)
    a, b = z[0] - d, z[1]
    return ((b - a) // 2, -(a + b) // 2)

def lsb(z: GaussInt) -> int:
    return 0 if z == (0, 0) else forced_digit(z)

def check(radius: int = 15) -> bool:
    for a in range(-radius, radius + 1):
        for b in range(-radius, radius + 1):
            if lsb((a, b)) != (a + b) % 2 and (a, b) != (0, 0):
                return False
    return True

if __name__ == "__main__":
    print("parity recovery holds on window:", check())
    for z in [(0, 1), (2, 3), (-5, 7), (4, 4)]:
        print(f"  z={z}: LSB={forced_digit(z)}, (Re+Im)%2={(z[0]+z[1]) % 2}")

